WITH matched_keys AS (SELECT supplier_id, id FROM products INTERSECT SELECT supplier_id, id FROM products WHERE SIZE(tags) >= 2), reconciled AS (SELECT s.* FROM products s INNER JOIN matched_keys k ON s.supplier_id = k.supplier_id AND s.id = k.id) SELECT id, product_name, category, stock_qty, launch_date, tags, supplier_id, CASE WHEN category RLIKE '^(Sports|Books)$' THEN 'EXTENDED' ELSE 'OTHER_ZONE' END AS category_zone FROM reconciled ORDER BY launch_date
